create extension if not exists pgcrypto;
create table if not exists companies (company_id uuid primary key default gen_random_uuid(), company_name text not null, industry text, country text default 'United Kingdom', created_at timestamptz default now());
create table if not exists analysis_runs (analysis_run_id text primary key, company_id uuid references companies(company_id), started_at timestamptz, completed_at timestamptz, status text not null default 'Queued', records_received integer default 0, records_processed integer default 0, records_rejected integer default 0, candidate_count integer default 0, high_confidence_count integer default 0, potential_recovery numeric(18,2) default 0, validated_recovery numeric(18,2) default 0, actual_recovered numeric(18,2) default 0, created_at timestamptz default now());
create table if not exists findings (finding_id text primary key, analysis_run_id text references analysis_runs(analysis_run_id), finding_type text not null, confidence text not null, status text not null default 'New', supplier_customer text, invoice_numbers jsonb, dates jsonb, amount numeric(18,2), currency text, potential_recovery numeric(18,2) default 0, validated_recovery numeric(18,2) default 0, actual_recovered numeric(18,2) default 0, evidence text, rule_triggered text, explanation text, recommended_action text, source_rows jsonb, review_notes text, owner text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists audit_log (log_id uuid primary key default gen_random_uuid(), analysis_run_id text references analysis_runs(analysis_run_id), event text not null, details jsonb, created_at timestamptz default now());
